STATES=['CREATED','INTAKE_VALIDATED','DORMANCY_ASSESSED','FRAMEWORK_BASELINED','ACE_ANALYSED','PLAN_APPROVED','IMPLEMENTING','BUILD_VALIDATED','DIFFERENTIAL_TESTING','VARIANCE_REVIEW','REMEDIATING','READY_FOR_PROMOTION','COMPLETED','STOPPED','ROLLED_BACK','FAILED',
'WAITING_G0','WAITING_G1','WAITING_G2','WAITING_G3','WAITING_G4','WAITING_G5']
TRANSITIONS={
'CREATED':{'INTAKE_VALIDATED','STOPPED','FAILED'},'INTAKE_VALIDATED':{'DORMANCY_ASSESSED','FRAMEWORK_BASELINED','WAITING_G0','STOPPED','FAILED'},
'DORMANCY_ASSESSED':{'FRAMEWORK_BASELINED','WAITING_G0','STOPPED','FAILED'},'FRAMEWORK_BASELINED':{'ACE_ANALYSED','WAITING_G1','STOPPED','FAILED'},
'ACE_ANALYSED':{'PLAN_APPROVED','WAITING_G2','STOPPED','FAILED'},'PLAN_APPROVED':{'IMPLEMENTING','WAITING_G3','STOPPED','FAILED'},
'IMPLEMENTING':{'BUILD_VALIDATED','FAILED','ROLLED_BACK'},'BUILD_VALIDATED':{'DIFFERENTIAL_TESTING','IMPLEMENTING','FAILED','ROLLED_BACK'},
'DIFFERENTIAL_TESTING':{'VARIANCE_REVIEW','FAILED','ROLLED_BACK'},'VARIANCE_REVIEW':{'REMEDIATING','READY_FOR_PROMOTION','WAITING_G4','STOPPED','ROLLED_BACK'},
'REMEDIATING':{'IMPLEMENTING','DIFFERENTIAL_TESTING','STOPPED','ROLLED_BACK'},'READY_FOR_PROMOTION':{'COMPLETED','WAITING_G5','DIFFERENTIAL_TESTING','STOPPED','ROLLED_BACK'},
'WAITING_G0':{'FRAMEWORK_BASELINED','STOPPED','FAILED'},'WAITING_G1':{'ACE_ANALYSED','STOPPED','FAILED'},
'WAITING_G2':{'PLAN_APPROVED','STOPPED','FAILED'},'WAITING_G3':{'IMPLEMENTING','STOPPED','FAILED'},
'WAITING_G4':{'REMEDIATING','READY_FOR_PROMOTION','STOPPED','FAILED'},'WAITING_G5':{'COMPLETED','STOPPED','FAILED'},
'FAILED':{'IMPLEMENTING','ROLLED_BACK','STOPPED'},'COMPLETED':set(),'STOPPED':set(),'ROLLED_BACK':set()}
class TransitionError(ValueError): pass
def validate_transition(current,target,open_clarifications=0):
    if target not in STATES: raise TransitionError('unknown_target_state')
    if open_clarifications and target not in {'STOPPED','FAILED','ROLLED_BACK'} and not target.startswith('WAITING_'): raise TransitionError('open_clarification_blocks_transition')
    if target not in TRANSITIONS.get(current,set()): raise TransitionError(f'illegal_transition:{current}->{target}')
    return True
